int[] ids = { 27, 93 };
Queue<int> line = new Queue<int>();
foreach (int id in ids) { line.Enqueue(id); }
if (line.Count > 0)
{
    int ticket = line.Dequeue();
    Console.WriteLine(ticket);
}
else { Console.WriteLine("فارغ"); }
Console.WriteLine(line.Count);

